create table public.overs_members (user_id uuid primary key references auth.users(id) on delete cascade, label text, created_at timestamptz default now());
create or replace function public.overs_is_member() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.overs_members where user_id = auth.uid()) $$;
create table public.overs_staff (id uuid primary key default gen_random_uuid(), name text not null unique, active boolean default true, created_at timestamptz default now());
create table public.overs_locations (id uuid primary key default gen_random_uuid(), name text not null unique, active boolean default true, sort int default 0);
create table public.overs_settings (key text primary key, value jsonb not null, updated_at timestamptz default now(), updated_by text);
create table public.overs_records (id uuid primary key default gen_random_uuid(), job_number text not null, customer text, location text, received_date date default (now() at time zone 'America/Chicago')::date, notes text, is_test boolean default false, created_by text, created_at timestamptz default now(), updated_at timestamptz default now());
create index on public.overs_records(job_number);
create table public.overs_products (id uuid primary key default gen_random_uuid(), record_id uuid not null references public.overs_records(id) on delete cascade, product_type text, description text, segment text, ocr_item_number text, verified_item_number text, quantity integer, label_date date, status text not null default 'NEEDS_REVIEW', status_reason text, eligible_at timestamptz, next_review_date date, review jsonb, final_check jsonb, completion jsonb, main_photo_id uuid, is_test boolean default false, created_by text, created_at timestamptz default now(), updated_at timestamptz default now());
create index on public.overs_products(record_id); create index on public.overs_products(status);
create table public.overs_containers (id uuid primary key default gen_random_uuid(), record_id uuid not null references public.overs_records(id) on delete cascade, product_id uuid references public.overs_products(id) on delete set null, count integer not null check (count > 0), container_type text not null, added_by text, added_at timestamptz default now());
create table public.overs_photos (id uuid primary key default gen_random_uuid(), record_id uuid not null references public.overs_records(id) on delete cascade, product_id uuid references public.overs_products(id) on delete set null, path text not null, thumb_path text, kind text, width int, height int, bytes int, created_by text, created_at timestamptz default now());
create table public.overs_reviews (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.overs_products(id) on delete cascade, data jsonb not null, computed_status text, checked_by text, checked_at timestamptz default now());
create table public.overs_events (id uuid primary key default gen_random_uuid(), record_id uuid references public.overs_records(id) on delete cascade, product_id uuid references public.overs_products(id) on delete cascade, event_type text not null, from_status text, to_status text, data jsonb, actor text, at timestamptz default now());
create index on public.overs_events(product_id);
do $$ declare t text; begin foreach t in array array['overs_members','overs_staff','overs_locations','overs_settings','overs_records','overs_products','overs_containers','overs_photos','overs_reviews','overs_events'] loop execute format('alter table public.%I enable row level security', t); end loop;
foreach t in array array['overs_staff','overs_locations','overs_settings','overs_records','overs_products','overs_containers','overs_photos'] loop execute format('create policy overs_sel on public.%I for select to authenticated using (public.overs_is_member())', t); execute format('create policy overs_ins on public.%I for insert to authenticated with check (public.overs_is_member())', t); execute format('create policy overs_upd on public.%I for update to authenticated using (public.overs_is_member()) with check (public.overs_is_member())', t); end loop;
foreach t in array array['overs_reviews','overs_events'] loop execute format('create policy overs_sel on public.%I for select to authenticated using (public.overs_is_member())', t); execute format('create policy overs_ins on public.%I for insert to authenticated with check (public.overs_is_member())', t); end loop; end $$;
create policy overs_photos_del on public.overs_photos for delete to authenticated using (public.overs_is_member());
create policy overs_containers_del on public.overs_containers for delete to authenticated using (public.overs_is_member());
create policy overs_self on public.overs_members for select to authenticated using (user_id = auth.uid());
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('overs-photos','overs-photos', false, 10485760, array['image/jpeg','image/png','image/webp']);
create policy overs_photos_obj_sel on storage.objects for select to authenticated using (bucket_id='overs-photos' and public.overs_is_member());
create policy overs_photos_obj_ins on storage.objects for insert to authenticated with check (bucket_id='overs-photos' and public.overs_is_member());
insert into public.overs_settings(key,value) values ('date_only_policy','"review"');
insert into public.overs_locations(name,sort) values ('Overs Area A',1),('Overs Area B',2),('Overs Rack',3),('Dock',4);;
